import test from 'node:test';
import assert from 'node:assert/strict';
import { prorate } from '../src/proration.js';

test('credits the unused half of a 30-day period', () => {
  const start = Date.UTC(2026, 10, 1);
  const end = Date.UTC(2026, 11, 1);
  const changed = Date.UTC(2026, 10, 16);
  assert.equal(prorate(30, start, end, changed), 15);
});

const HOUR = 60 * 60 * 1000;
const near = (actual, expected) =>
  assert.ok(Math.abs(actual - expected) < 1e-9, `expected ${expected}, got ${actual}`);

test('credits a mid-day plan change for the fraction of the day left', () => {
  const start = Date.UTC(2026, 10, 1);
  const end = Date.UTC(2026, 11, 1);
  const changed = Date.UTC(2026, 10, 16, 12); // noon: 14.5 of 30 days unused
  assert.equal(prorate(30, start, end, changed), 14.5);
});

test('a change shortly after period start or before period end is not rounded to a whole day', () => {
  const start = Date.UTC(2026, 10, 1);
  const end = Date.UTC(2026, 11, 1);
  // 1h into the period: slightly less than the full price is credited.
  near(prorate(30, start, end, start + HOUR), 30 - 1 / 24);
  // 1h before the period ends: a small non-zero credit remains.
  near(prorate(30, start, end, end - HOUR), 1 / 24);
});

test('returns a finite credit for a period shorter than a day', () => {
  const start = Date.UTC(2026, 10, 1);
  const end = start + 6 * HOUR;
  near(prorate(10, start, end, start + 3 * HOUR), 5);
});
