const HOUR = 60 * 60 * 1000;
const near = (actual, expected) =>
  assert.ok(Math.abs(actual - expected) < 1e-9, `expected ${expected}, got ${actual}`);

test('credits a mid-day plan change for the fraction of the day left', () => {
